class Solution {
    int MOD = 1e9 + 7;
    int memo[105][11][2][2];
    int dp(int idx, int prev, bool is_tight, bool started, const string& s) {
        if (idx == s.size()) return started ? 1 : 0;
        int p_idx = prev == -1 ? 10 : prev;
        if (memo[idx][p_idx][is_tight][started] != -1) return memo[idx][p_idx][is_tight][started];
        int limit = is_tight ? (s[idx] - '0') : 9;
        long long ans = 0;
        for (int d = 0; d <= limit; ++d) {
            bool nxt_tight = is_tight && (d == limit);
            if (!started) {
                if (d == 0) ans = (ans + dp(idx + 1, -1, nxt_tight, false, s)) % MOD;
                else ans = (ans + dp(idx + 1, d, nxt_tight, true, s)) % MOD;
            } else {
                if (abs(d - prev) == 1) ans = (ans + dp(idx + 1, d, nxt_tight, true, s)) % MOD;
            }
        }
        return memo[idx][p_idx][is_tight][started] = ans;
    }
    int count_up_to(const string& s) {
        memset(memo, -1, sizeof(memo));
        return dp(0, -1, true, false, s);
