import java.math.BigInteger;
import java.util.Arrays;

class Solution {
    private static final int MOD = 1_000_000_007;
    private int[][][][] memo;

    private int dp(int idx, int prev, boolean isTight, boolean started, String s) {
        if (idx == s.length()) return started ? 1 : 0;
        int pIdx = prev == -1 ? 10 : prev;
        int tIdx = isTight ? 1 : 0;
        int sIdx = started ? 1 : 0;
        if (memo[idx][pIdx][tIdx][sIdx] != -1) return memo[idx][pIdx][tIdx][sIdx];
        int limit = isTight ? (s.charAt(idx) - '0') : 9;
        long ans = 0;
        for (int d = 0; d <= limit; d++) {
            boolean nxtTight = isTight && (d == limit);
            if (!started) {
                if (d == 0) ans = (ans + dp(idx + 1, -1, nxtTight, false, s)) % MOD;
                else ans = (ans + dp(idx + 1, d, nxtTight, true, s)) % MOD;
            } else {
                if (Math.abs(d - prev) == 1) ans = (ans + dp(idx + 1, d, nxtTight, true, s)) % MOD;
            }
        }
        return memo[idx][pIdx][tIdx][sIdx] = (int) ans;
    }

    private int countUpTo(String s) {
        memo = new int[s.length()][11][2][2];
        for (int[][][] a : memo) for (int[][] b : a) for (int[] c : b) Arrays.fill(c, -1);
        return dp(0, -1, true, false, s);
    }

    public int countSteppingNumbers(String low, String high) {
        int ans = countUpTo(high);
        BigInteger lowVal = new BigInteger(low).subtract(BigInteger.ONE);
        int sub = countUpTo(lowVal.toString());
        return (ans - sub + MOD) % MOD;
    }
}

