var countSteppingNumbers = function(low, high) {
    const MOD = 1000000007n;
    function countUpTo(s) {
        const memo = new Map();
        function dp(idx, prev, isTight, started) {
            if (idx === s.length) return started ? 1n : 0n;
            const key = `${idx},${prev},${isTight ? 1 : 0},${started ? 1 : 0}`;
            if (memo.has(key)) return memo.get(key);
            const limit = isTight ? Number(s[idx]) : 9;
            let ans = 0n;
            for (let d = 0; d <= limit; d++) {
                const nxtTight = isTight && d === limit;
                if (!started) {
                    if (d === 0) ans = (ans + dp(idx + 1, -1, nxtTight, false)) % MOD;
                    else ans = (ans + dp(idx + 1, d, nxtTight, true)) % MOD;
                } else {
                    if (Math.abs(d - prev) === 1) ans = (ans + dp(idx + 1, d, nxtTight, true)) % MOD;
                }
            }
            memo.set(key, ans);
            return ans;
        }
        return dp(0, -1, true, false);
    }
    const lowSub = (BigInt(low) - 1n).toString();
    const ans = (countUpTo(high) - countUpTo(lowSub) + MOD) % MOD;
    return Number(ans);
};
